【帮我写一个drm加密，用于加密我上传到网页的图片和照片】折叠的第 6 步：[已折叠] write_file(path='drm_server.py'，content='"""
DRM 加密后端服务
提供密钥管理和照片验证功能
"""

from flask import Flask, request, jsonify, send_file
from flask_cors import CORS
from cryptography.hazmat.primitives.ciphers.aead import AESGCM
from cryptography.hazmat.primitives import hashes
from cryptography.hazmat.backends import default_backend
import os
import json
import base64
import uuid
from datetime import datetime
import secrets

app = Flask(__name__)
CORS(app)

# 配置
SECRET_KEY = os.environ.get('DRM_SECRET_KEY', secrets.token_hex(32))
ENCRYPTION_KEY = os.environ.get('DRM_ENCRYPTION_KEY', secrets.token_hex(32))
DATA_DIR = 'encrypted_photos'
os.makedirs(DATA_DIR, exist_ok=True)

# 密钥管理
class KeyManager:
    def __init__(self):
        self.key_file = 'drm_key.json'
        self.load_key()

    def load_key(self):
        """加载或生成加密密钥"""
        if os.path.exists(self.key_file):
            with open(self.key_file, 'r') as f:
                self.key = json.load(f)
        else:
            self.key = {
                'encryption_key': ENCRYPTION_KEY,
                'created_at': datetime.now().isoformat(),
                'last_updated': datetime.now().isoformat()
            }
            self.save_key()

    def save_key(self):
        """保存加密密钥"""
        self.key['last_updated'] = datetime.now().isoformat()
        with open(self.key_file, 'w') as f:
            json.dump(self.key, f, indent=2)

    def get_key(self):
        """获取加密密钥"""
        return self.key.get('encryption_key')

    def verify_key(self, provided_key):
        """验证提供的密钥"""
        return self.key.get('encryption_key') == provided_key

key_manager = KeyManager()

# 照片存储
class PhotoStore:
    def __init__(self):
        self.photos_file = 'photos_index.json'
        self.photos = self.load_photos()

    def load_photos(self):
        """加载照片索引"""
        if os.path.exists(self.photos_file):
            with open(self.photos_file, 'r', encoding='utf-8') as f:
                return json.load(f)
        return []

    def save_photos(self):
        """保存照片索引"""
        with open(self.photos_file, 'w', encoding='utf-8') as f:
            json.dump(self.photos, f, ensure_ascii=False, indent=2)

    def add_photo(self, photo_data):
        """添加照片"""
        self.photos.append(photo_data)
        self.save_photos()
        return photo_data

    def get_photos(self):
        """获取所有照片"""
        return self.photos

    def get_photo(self, photo_id):
        """获取指定照片"""
        for photo in self.photos:
            if photo['id'] == photo_id:
                return photo
        return None

    def delete_photo(self, photo_id):
        """删除照片"""
        self.photos = [p for p in self.photos if p['id'] != photo_id]
        self.save_photos()
        return True

photo_store = PhotoStore()

# 加密/解密函数
def encrypt_image(image_data, key):
    """加密图片数据"""
    aesgcm = AESGCM(key.encode())
    nonce = secrets.token_bytes(12)
    encrypted = aesgcm.encrypt(nonce, image_data.encode(), None)
    return base64.b64encode(nonce + encrypted).decode()

def decrypt_image(encrypted_data, key):
    """解密图片数据"""
    try:
        aesgcm = AESGCM(key.encode())
        nonce_and_encrypted = base64.b64decode(encrypted_data)
        nonce = nonce_and_encrypted[:12]
        encrypted = nonce_and_encrypted[12:]
        decrypted = aesgcm.decrypt(nonce, encrypted, None)
        return decrypted.decode()
    except Exception as e:
        raise Exception(f'解密失败：{str(e)}')

# API 路由
@app.route('/api/key', methods=['GET'])
def get_key():
    """获取加密密钥（需要验证）"""
    auth_token = request.headers.get('Authorization', '').replace('Bearer ', '')

    if not auth_token:
        return jsonify({'error': '缺少认证令牌'}), 401

    if not key_manager.verify_key(auth_token):
        return jsonify({'error': '密钥验证失败'}), 403

    return jsonify({
        'status': 'success',
        'message': '密钥验证成功'
    })

@app.route('/api/upload', methods=['POST'])
def upload_photo():
    """上传并加密照片"""
    try:
        auth_token = request.headers.get('Authorization', '').replace('Bearer ', '')

        if not auth_token:
            return jsonify({'error': '缺少认证令牌'}), 401

        if not key_manager.verify_key(auth_token):
            return jsonify({'error': '密钥验证失败'}), 403

        # 获取文件
        if 'file' not in request.files:
            return jsonify({'error': '未找到文件'}), 400

        file = request.files['file']
        if file.filename == '':
            return jsonify({'error': '文件名为空'}), 400

        # 读取文件
        image_data = file.read()

        # 加密
        encrypted_data = encrypt_image(image_data, key_manager.get_key())

        # 创建照片记录
        photo_id = str(uuid.uuid4())
        photo_data = {
            'id': photo_id,
            'filename': file.filename,
            'original_name': file.filename.split('.')[0],
            'title': file.filename.split('.')[0],
            'date': datetime.now().isoformat(),
            'encrypted_data': encrypted_data,
            'encryption_key': key_manager.get_key(),
            'version': '1.0'
        }

        # 保存到存储
        photo_store.add_photo(photo_data)

        return jsonify({
            'status': 'success',
            'message': '照片上传成功',
            'photo_id': photo_id,
            'photo': photo_data
        }), 201

    except Exception as e:
        return jsonify({'error': str(e)}), 500

@app.route('/api/photos', methods=['GET'])
def get_photos():
    """获取所有照片列表"""
    auth_token = request.headers.get('Authorization', '').replace('Bearer ', '')

    if not auth_token:
        return jsonify({'error': '缺少认证令牌'}), 401

    if not key_manager.verify_key(auth_token):
        return jsonify({'error': '密钥验证失败'}), 403

    photos = photo_store.get_photos()
    return jsonify({
        'status': 'success',
        'photos': photos
    })

@app.route('/api/photos/<photo_id>', methods=['GET'])
def get_photo(photo_id):
    """获取指定照片"""
    auth_token = request.headers.get('Authorization', '').replace('Bearer ', '')

    if not auth_token:
        return jsonify({'error': '缺少认证令牌'}), 401

    if not key_manager.verify_key(auth_token):
        return jsonify({'error': '密钥验证失败'}), 403

    photo = photo_store.get_photo(photo_id)

    if not photo:
        return jsonify({'error': '照片不存在'}), 404

    return jsonify({
        'status': 'success',
        'photo': photo
    })

@app.route('/api/photos/<photo_id>', methods=['DELETE'])
def delete_photo(photo_id):
    """删除照片"""
    auth_token = request.headers.get('Authorization', '').replace('Bearer ', '')

    if not auth_token:
        return jsonify({'error': '缺少认证令牌'}), 401

    if not key_manager.verify_key(auth_token):
        return jsonify({'error': '密钥验证失败'}), 403

    if photo_store.delete_photo(photo_id):
        return jsonify({
            'status': 'success',
            'message': '照片已删除'
        })

    return jsonify({'error': '照片不存在'}), 404

@app.route('/api/decrypt/<photo_id>', methods=['POST'])
def decrypt_photo(photo_id):
    """解密并返回照片"""
    auth_token = request.headers.get('Authorization', '').replace('Bearer ', '')

    if not auth_token:
        return jsonify({'error': '缺少认证令牌'}), 401

    if not key_manager.verify_key(auth_token):
        return jsonify({'error': '密钥验证失败'}), 403

    photo = photo_store.get_photo(photo_id)

    if not photo:
        return jsonify({'error': '照片不存在'}), 404

    try:
        decrypted_data = decrypt_image(photo['encrypted_data'], key_manager.get_key())

        # 返回图片文件
        return send_file(
            '/dev/null',
            mimetype='image/jpeg',
            response=decrypted_data.encode()
        )
    except Exception as e:
        return jsonify({'error': str(e)}), 500

@app.route('/api/export', methods=['POST'])
def export_photos():
    """导出所有照片（加密格式）"""
    auth_token = request.headers.get('Authorization', '').replace('Bearer ', '')

    if not auth_token:
        return jsonify({'error': '缺少认证令牌'}), 401

    if not key_manager.verify_key(auth_token):
        return jsonify({'error': '密钥验证失败'}), 403

    photos = photo_store.get_photos()

    export_data = {
        'version': '1.0',
        'timestamp': datetime.now().isoformat(),
        'photos': photos
    }

    response = jsonify(export_data)
    response.headers['Content-Disposition'] = f'attachment; filename="campus_photos_{datetime.now().strftime("%Y%m%d")}.drm"'

    return response

@app.route('/api/verify', methods=['POST'])
def verify_key():
    """验证密钥"""
    data = request.get_json()
    provided_key = data.get('key')

    if not provided_key:
        return jsonify({'error': '缺少密钥'}), 400

    if key_manager.verify_key(provided_key):
        return jsonify({
            'status': 'success',
            'message': '密钥验证成功'
        })

    return jsonify({'error': '密钥无效'}), 403

if __name__ == '__main__':
    print("=== DRM 加密后端服务启动 ===")
    print(f"密钥文件：{key_manager.key_file}")
    print(f"照片索引：{photo_store.photos_file}")
    print(f"数据目录：{DATA_DIR}")
    print("按 Ctrl+C 停止服务")
    app.run(host='0.0.0.0', port=5000, debug=True)
