 * DRM 图片加密器
 * 使用 AES-GCM 对图片数据进行加密和解密
 */
class DRMEncryptor {
    constructor() {
        this.algo = 'AES-GCM';
        this.version = '1.0';
    }

    /**
     * 生成随机密钥（256 位）
     * @returns {string} Base64 编码的密钥
     */
    generateKey() {
        const array = new Uint8Array(32); // 256 位 = 32 字节
        window.crypto.getRandomValues(array);
        return btoa(String.fromCharCode(...Array.from(array)));
    }

    /**
     * 生成随机 IV（12 字节）
     * @returns {string} Base64 编码的 IV
     */
    generateIV() {
        const array = new Uint8Array(12); // GCM 模式需要 12 字节 IV
        window.crypto.getRandomValues(array);
        return btoa(String.fromCharCode(...Array.from(array)));
    }

    /**
     * 加密图片数据
     * @param {string} imageData - Base64 编码的图片数据
     * @param {string} keyBase64 - Base64 编码的密钥
     * @returns {Promise} 加密结果
     */
    async encrypt(imageData, keyBase64) {
        try {
            const key = this.base64ToKey(keyBase64);
            const iv = this.generateIV();

            // 解码图片数据
            const imageBytes = await this.base64ToArrayBuffer(imageData);

            // 加密
            const encrypted = await window.crypto.subtle.encrypt(
                { name: this.algo, iv: this.arrayBufferToUint8Array(iv) },
                key,
                imageBytes
            );

            return {
                encryptedData: btoa(String.fromCharCode(...Array.from(new Uint8Array(encrypted)))),
                iv: iv,
                timestamp: Date.now(),
                version: this.version
            };
        } catch (error) {
            console.error('加密错误:', error);
            throw error;
        }
    }

    /**
     * 解密图片数据
     * @param {string} encryptedDataBase64 - Base64 编码的加密数据
     * @param {string} keyBase64 - Base64 编码的密钥
     * @param {string} ivBase64 - Base64 编码的 IV
     * @returns {Promise} 解密结果
     */
    async decrypt(encryptedDataBase64, keyBase64, ivBase64) {
        try {
            const key = this.base64ToKey(keyBase64);
            const iv = this.arrayBufferToUint8Array(this.base64ToArrayBuffer(ivBase64));

            // 解码加密数据
            const encryptedBytes = await this.base64ToArrayBuffer(encryptedDataBase64);

            // 解密
            const decrypted = await window.crypto.subtle.decrypt(
                { name: this.algo, iv },
                key,
                encryptedBytes
            );

            return {
                decryptedData: btoa(String.fromCharCode(...Array.from(new Uint8Array(decrypted)))),
                timestamp: Date.now(),
                version: this.version
            };
        } catch (error) {
            console.error('解密错误:', error);
            throw error;
        }
    }

