                <div class="upload-text">点击或拖拽图片到这里上传</div>
                <input type="file" class="file-input" id="fileInput" accept="image/*" multiple>
            </div>

            <div class="form-group">
                <label for="noteText">📝 备注文字：</label>
                <textarea id="noteText" placeholder="写下这张照片的故事..."></textarea>
            </div>

            <button class="btn" id="uploadBtn">上传记录</button>

            <div class="loading" id="loading">正在上传...</div>
