    <script>
        // 使用 localStorage 存储数据（前端实现）
        const STORAGE_KEY = 'campus_photos';

        // 初始化加载
        document.addEventListener('DOMContentLoaded', () => {
            loadPhotos();
        });

        // 拖拽上传功能
        const uploadArea = document.getElementById('uploadArea');
        const fileInput = document.getElementById('fileInput');
        const noteText = document.getElementById('noteText');
        const uploadBtn = document.getElementById('uploadBtn');
        const loading = document.getElementById('loading');

        uploadArea.addEventListener('click', () => fileInput.click());

        uploadArea.addEventListener('dragover', (e) => {
            e.preventDefault();
            uploadArea.classList.add('dragover');
        });

        uploadArea.addEventListener('dragleave', () => {
            uploadArea.classList.remove('dragover');
        });

        uploadArea.addEventListener('drop', (e) => {
            e.preventDefault();
            uploadArea.classList.remove('dragover');
            const files = Array.from(e.dataTransfer.files).filter(file => 
                file.type.startsWith('image/')
            );
            if (files.length > 0) {
                handleFiles(files);
            }
        });

        fileInput.addEventListener('change', (e) => {
            const files = Array.from(e.target.files).filter(file => 
                file.type.startsWith('image/')
            );
            if (files.length > 0) {
                handleFiles(files);
            }
        });

        function handleFiles(files) {
            noteText.value = ''; // 清空备注，因为每张图片可以有独立备注
            uploadBtn.click();
        }

        uploadBtn.addEventListener('click', () => {
            const files = fileInput.files;
            if (files.length === 0) {
                alert('请先选择图片！');
                return;
            }

            loading.style.display = 'block';

            Array.from(files).forEach(file => {
                const reader = new FileReader();
                reader.onload = (e) => {
                    const photoData = {
                        id: Date.now() + Math.random(),
                        image: e.target.result,
                        note: noteText.value,
                        date: new Date().toLocaleString('zh-CN')
                    };

                    savePhoto(photoData);
                };
                reader.readAsDataURL(file);
            });

            // 上传完成后清空文件输入
            fileInput.value = '';
        });

        function savePhoto(photo) {
            let photos = getPhotos();
            photos.unshift(photo); // 添加到开头
            localStorage.setItem(STORAGE_KEY, JSON.stringify(photos));
            loadPhotos();
        }

        function getPhotos() {
            const data = localStorage.getItem(STORAGE_KEY);
            return data ? JSON.parse(data) : [];
        }

        function loadPhotos() {
            const gallery = document.getElementById('gallery');
            const photos = getPhotos();

            if (photos.length === 0) {
                gallery.innerHTML = `
                    <div class="empty-state">
                        <h2>🌟 还没有照片记录</h2>
                        <p>点击上方区域上传你的第一张校园生活照片吧！</p>
                    </div>
                `;
                return;
            }

            gallery.innerHTML = photos.map(photo => `
                <div class="photo-card">
                    <img src="${photo.image}" alt="校园生活记录" class="photo-image">
                    <div class="photo-content">
                        ${photo.note ? `<p class="photo-text">${escapeHtml(photo.note)}</p>` : ''}
                        <p class="photo-date">📅 ${photo.date}</p>
                        <button class="delete-btn" onclick="deletePhoto(${photo.id})">删除</button>
                    </div>
                </div>
            `).join('');
        }

        function escapeHtml(text) {
            const div = document.createElement('div');
            div.textContent = text;
            return div.innerHTML;
        }

        window.deletePhoto = function(id) {
            if (!confirm('确定要删除这条记录吗？')) return;

            let photos = getPhotos();
            photos = photos.filter(photo => photo.id !== id);
            localStorage.setItem(STORAGE_KEY, JSON.stringify(photos));
            loadPhotos();
        };
    </script>
